      if (/bottom-sheet/.test(kind)) return profile(["trigger", "Trigger / anchor", "Control or gesture that opens the sheet."], ["content", "Sheet content", "Heading and actions, one per line."], ["dismiss", "Dismissal / state", "Half or full height, drag handle, backdrop, and close behavior."], ["action", "Primary action", "Main action or destination."], ["accessibility", "Accessibility", "Dialog label, focus entry, and focus return."]);
      if (/tooltip|popover|command-palette/.test(kind)) return profile(["trigger", "Trigger / anchor", "Control, gesture, or shortcut that opens this surface."], ["content", "Content / commands", "Text, choices, or commands shown, one per line."], ["dismiss", "Dismissal / state", "How it opens, closes, and handles focus."], ["action", "Action / keyboard", "Primary action, shortcut, or destination."], ["accessibility", "Accessibility", "Accessible name, focus behavior, and keyboard navigation."]);
      if (/empty-state/.test(kind)) return profile(["status", "Heading / status", "Short empty-state heading."], ["details", "Explanation", "Why this view has no content and what belongs here."], ["recovery", "Primary action", "Next step or action label."], ["accessibility", "Accessibility", "Announcement, illustration text alternative, and focus target."]);
      if (/skeleton-loading-state/.test(kind)) return profile(["content", "Content shape", "Choose list, cards, table, or form; one region per line."], ["state", "Loading state", "Loading message or progress indication."], ["interaction", "Expected content", "What will replace the placeholders when loading finishes."], ["accessibility", "Accessibility", "Busy state and announcement timing."]);
      if (/error-state/.test(kind)) return profile(["status", "Error heading", "What failed, stated clearly."], ["details", "Error details", "Cause or diagnostic context safe to show."], ["recovery", "Recovery action", "Retry, resolve, or return action."], ["accessibility", "Accessibility", "Alert semantics, announcement, and focus target."]);
      if (/loading-indicator/.test(kind)) return profile(["progress", "Progress", "Optional percentage from 0 to 100."], ["status", "Status message", "What is loading and what is happening."], ["state", "Loading behavior", "Indeterminate or determinate progress and expected duration."], ["accessibility", "Accessibility", "Progressbar label and value announcement."]);
      if (/sign-in-panel/.test(kind)) return profile(["identity", "Identity field", "Email, username, or account label."], ["secret", "Secret field", "Password or verification code field label."], ["validation", "Validation / helper", "Inline error or sign-in guidance."], ["action", "Primary action", "Sign-in action and optional secondary link."], ["accessibility", "Accessibility", "Labels, error association, password visibility, and focus order."]);
      if (/file-drop-zone/.test(kind)) return profile(["accepted", "Accepted files", "File extensions, types, and size limit."], ["content", "Drop message", "Prompt and drag-and-drop instructions."], ["state", "Drop state", "Idle, dragging, invalid, or uploaded state."], ["action", "Browse action", "Button label and file-picker behavior."], ["accessibility", "Accessibility", "Keyboard file selection and announced upload state."]);
